import 'package:common/constants/failure_class.dart';
import 'package:dartz/dartz.dart';
import 'package:domain/core/usecase.dart';
import 'package:domain/modules/chat/chat_repository.dart';

class SendMessageUseCase extends UseCase<void, SendMessageParams> {
  final ChatRepository repository;

  SendMessageUseCase({required this.repository});

  @override
  Future<Either<Failure, void>> call(SendMessageParams params) async {
    try {
      await repository.sendMessage(
        chatId: params.chatId,
        senderId: params.senderId,
        text: params.text,
        type: params.type,
        mediaUrl: params.mediaUrl,
      );
      return Right(null);
    } catch (e) {
      return Left(e as Failure);
    }
  }
}

class SendMessageParams {
  final String chatId;
  final String senderId;
  final String text;
  final String type;
  final String? mediaUrl;

  SendMessageParams({
    required this.chatId,
    required this.senderId,
    required this.text,
    this.type = 'text',
    this.mediaUrl,
  });
}

import 'package:common/constants/failure_class.dart';
import 'package:dartz/dartz.dart';
import 'package:domain/core/usecase.dart';
import 'package:domain/modules/chat/chat_repository.dart';

class SendMessageUseCase extends UseCase<void, SendMessageParams> {
  final ChatRepository repository;

  SendMessageUseCase({required this.repository});

  @override
  Future<Either<Failure, void>> call(SendMessageParams params) async {
    try {
      await repository.sendMessage(
        chatId: params.chatId,
        senderId: params.senderId,
        text: params.text,
        type: params.type,
        mediaUrl: params.mediaUrl,
      );
      return Right(null);
    } catch (e, stackTrace) {
      return Left(Failure.error(e, stackTrace));
    }
  }
}

class SendMessageParams {
  final String chatId;
  final String senderId;
  final String text;
  final String type;
  final String? mediaUrl;

  SendMessageParams({
    required this.chatId,
    required this.senderId,
    required this.text,
    this.type = 'text',
    this.mediaUrl,
  });
}

import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';
import 'package:presentation/util/resources/texts_styles.dart';

import '../resources/app_colors.dart';

class TextFieldViewItem {
  final String? hintText;
  final String? labelText;
  final TextInputType? keyboardType;
  final List<String>? autofillHints;
  final Widget? prefixIcon;
  final String? Function(String?)? validator;
  final bool isPassword;
  final TextEditingController? controller;

  const TextFieldViewItem({
    this.controller,
    this.hintText,
    this.labelText,
    this.keyboardType,
    this.autofillHints,
    this.prefixIcon,
    this.validator,
    this.isPassword = false,
  });
}

class TextFormFieldWidget extends StatefulWidget {
  final TextFieldViewItem item;

  const TextFormFieldWidget({super.key, required this.item});

  @override
  State<TextFormFieldWidget> createState() => _TextFormFieldWidgetState();
}

class _TextFormFieldWidgetState extends State<TextFormFieldWidget> {
  bool isObscure = false;
  TextEditingController editingController = .new();

  @override
  Widget build(BuildContext context) {
    final item = widget.item;
    return TextFormField(
      controller: item.controller,
      keyboardType: item.keyboardType,
      autofillHints: item.autofillHints,
      obscureText: item.isPassword ? isObscure : false,
      validator: item.validator,
      style: TextsStyles.input,
      decoration: InputDecoration(
        prefixIcon: item.prefixIcon,
        suffixIcon: item.isPassword
            ? IconButton(
                color: AppColors.hintColor,
                onPressed: () {
                  setState(() => isObscure = !isObscure);
                },
                icon: Icon(
                  isObscure ? Icons.visibility_off_outlined : Icons.visibility_outlined,
                  color: AppColors.hintColor,
                  size: 20.w,
                ),
              )
            : null,
        hintText: item.hintText,
        labelText: item.labelText,
        isDense: true,
        hintStyle:  TextsStyles.hint,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(15.r),
          borderSide: const BorderSide(color: AppColors.borderColor),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(15.r),
          borderSide: const BorderSide(color: AppColors.borderColor),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(25.r),
          borderSide: BorderSide(color: AppColors.primaryCian, width: 2.w),
        ),
      ),
      onTapOutside: (_) {
        FocusManager.instance.primaryFocus?.unfocus();
      },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_screenutil/flutter_screenutil.dart';
import 'package:presentation/util/resources/texts_styles.dart';

import '../resources/app_colors.dart';

class TextFieldViewItem {
  final String? hintText;
  final String? labelText;
  final TextInputType? keyboardType;
  final List<String>? autofillHints;
  final Widget? prefixIcon;
  final String? Function(String?)? validator;
  final bool isPassword;
  final TextEditingController? controller;

  const TextFieldViewItem({
    this.controller,
    this.hintText,
    this.labelText,
    this.keyboardType,
    this.autofillHints,
    this.prefixIcon,
    this.validator,
    this.isPassword = false,
  });
}

class TextFormFieldWidget extends StatefulWidget {
  final TextFieldViewItem item;

  const TextFormFieldWidget({super.key, required this.item});

  @override
  State<TextFormFieldWidget> createState() => _TextFormFieldWidgetState();
}

class _TextFormFieldWidgetState extends State<TextFormFieldWidget> {
  bool isObscure = false;
  TextEditingController editingController = .new();

  @override
  Widget build(BuildContext context) {
    final item = widget.item;
    return TextFormField(
      controller: editingController,
      autovalidateMode: AutovalidateMode.onUserInteraction,
      keyboardType: item.keyboardType,
      autofillHints: item.autofillHints,
      obscureText: item.isPassword ? isObscure : false,
      validator: item.validator,
      style: TextsStyles.input,
      decoration: InputDecoration(
        prefixIcon: item.prefixIcon,
        suffixIcon: item.isPassword
            ? IconButton(
                color: AppColors.hintColor,
                onPressed: () {
                  setState(() => isObscure = !isObscure);
                },
                icon: Icon(
                  isObscure ? Icons.visibility_off_outlined : Icons.visibility_outlined,
                  color: AppColors.hintColor,
                  size: 20.w,
                ),
              )
            : null,
        hintText: item.hintText,
        labelText: item.labelText,
        isDense: true,
        hintStyle:  TextsStyles.hint,
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(15.r),
          borderSide: const BorderSide(color: AppColors.borderColor),
        ),
        enabledBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(15.r),
          borderSide: const BorderSide(color: AppColors.borderColor),
        ),
        focusedBorder: OutlineInputBorder(
          borderRadius: BorderRadius.circular(25.r),
          borderSide: BorderSide(color: AppColors.primaryCian, width: 2.w),
        ),
      ),
      onTapOutside: (_) {
        FocusManager.instance.primaryFocus?.unfocus();
      },
    );
  }
}

